CREATE TABLE training_learning_path(id BIGINT NOT NULL,position_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(200) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),INDEX idx_training_path_position(position_code,enabled));
CREATE TABLE training_course(id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,description TEXT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'DRAFT',pass_score INT UNSIGNED NOT NULL DEFAULT 60,estimated_minutes INT UNSIGNED NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT chk_training_pass_score CHECK(pass_score<=100));
CREATE TABLE training_path_course(path_id BIGINT NOT NULL,course_id BIGINT NOT NULL,sequence_no INT UNSIGNED NOT NULL,prerequisite_course_id BIGINT NULL,PRIMARY KEY(path_id,course_id),UNIQUE KEY uk_training_path_sequence(path_id,sequence_no));
CREATE TABLE training_chapter(id BIGINT NOT NULL,course_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,sequence_no INT UNSIGNED NOT NULL,minimum_active_seconds INT UNSIGNED NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_training_chapter_sequence(course_id,sequence_no),CONSTRAINT fk_training_chapter_course FOREIGN KEY(course_id) REFERENCES training_course(id) ON DELETE CASCADE);
CREATE TABLE training_document(id BIGINT NOT NULL,chapter_id BIGINT NOT NULL,file_name VARCHAR(255) NOT NULL,media_type VARCHAR(128) NOT NULL,storage_key VARCHAR(512) NOT NULL,sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ACTIVE',PRIMARY KEY(id),INDEX idx_training_document_chapter(chapter_id));
CREATE TABLE training_gate(id BIGINT NOT NULL,chapter_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,pass_score INT UNSIGNED NOT NULL,maximum_attempts INT UNSIGNED NULL,PRIMARY KEY(id),UNIQUE KEY uk_training_gate_chapter(chapter_id));
CREATE TABLE training_question(id BIGINT NOT NULL,gate_id BIGINT NOT NULL,question_type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,stem TEXT NOT NULL,options_json JSON NULL,correct_answer_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,explanation TEXT NULL,score INT UNSIGNED NOT NULL,PRIMARY KEY(id),INDEX idx_training_question_gate(gate_id));
CREATE TABLE training_assignment(id BIGINT NOT NULL,user_id BIGINT NOT NULL,path_id BIGINT NULL,course_id BIGINT NOT NULL,assigned_by BIGINT NOT NULL,due_at DATETIME(6) NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ASSIGNED',assigned_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),completed_at DATETIME(6) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),INDEX idx_training_assignment_user_status(user_id,status,due_at));
CREATE TABLE training_chapter_progress(assignment_id BIGINT NOT NULL,chapter_id BIGINT NOT NULL,active_seconds INT UNSIGNED NOT NULL DEFAULT 0,last_nonce VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NULL,completed BOOLEAN NOT NULL DEFAULT FALSE,completed_at DATETIME(6) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(assignment_id,chapter_id),CONSTRAINT fk_training_progress_assignment FOREIGN KEY(assignment_id) REFERENCES training_assignment(id) ON DELETE CASCADE);
CREATE TABLE training_quiz_attempt(id BIGINT NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,assignment_id BIGINT NOT NULL,gate_id BIGINT NOT NULL,user_id BIGINT NOT NULL,score INT UNSIGNED NOT NULL,passed BOOLEAN NOT NULL,answers_json JSON NOT NULL,started_at DATETIME(6) NOT NULL,submitted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_training_attempt_request(request_id),INDEX idx_training_attempt_assignment_gate(assignment_id,gate_id,submitted_at));
CREATE TABLE training_weakness(user_id BIGINT NOT NULL,knowledge_code VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,wrong_count INT UNSIGNED NOT NULL DEFAULT 0,last_wrong_at DATETIME(6) NOT NULL,PRIMARY KEY(user_id,knowledge_code));
